W,H=780,640; L,R=70,24
PANELS=((LOW,24,280,'peak learning rate 1.5 × 10⁻³ (the main run’s)'),(HIGH,330,586,'peak learning rate 12 × 10⁻³ (8 times higher)'))
Y0,Y1=6.0,11.5
def sx(s): return L+s/150*(W-L-R)
def svg(th,cat):
    ink,mut,grid,surf=th; c1,c2,c3=cat
    sty=((c2,''),(c2,' stroke-dasharray="5 4"'),(c1,''),(c3,''))
    o=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" font-family="Arial,Helvetica,sans-serif" role="img">']
    o.append(f'<rect width="{W}" height="{H}" fill="{surf}"/>')
    for runs,a,b,title in PANELS:
        sy=lambda y,a=a,b=b: b-(y-Y0)/(Y1-Y0)*(b-a)
        for y in (6,7,8,9,10,11):
            o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(y):.1f}" y2="{sy(y):.1f}" stroke="{grid}" stroke-width="1"/>')
            o.append(f'<text x="{L-8}" y="{sy(y)+4:.1f}" fill="{mut}" font-size="13" text-anchor="end">{y}</text>')
        for s in range(0,151,25):
            o.append(f'<line x1="{sx(s):.1f}" x2="{sx(s):.1f}" y1="{a}" y2="{b}" stroke="{grid}" stroke-width="1"/>')
        o.append(f'<line x1="{L}" x2="{W-R}" y1="{sy(7.59):.1f}" y2="{sy(7.59):.1f}" stroke="{mut}" stroke-width="1.2" stroke-dasharray="2 4"/>')
        o.append(f'<text x="{W-R-6}" y="{a+16}" fill="{ink}" font-size="14" font-weight="bold" text-anchor="end">{title}</text>')
        for run,(c,d) in zip(runs,sty):
            pts=' '.join(f'{sx(i):.1f},{sy(min(v,Y1)):.1f}' for i,v in enumerate(run))
            o.append(f'<polyline points="{pts}" fill="none" stroke="{c}" stroke-width="2"{d}/>')
        o.append(f'<text transform="translate(20,{(a+b)/2}) rotate(-90)" fill="{ink}" font-size="14" text-anchor="middle">Training loss</text>')
    for s in range(0,151,25):
        o.append(f'<text x="{sx(s):.1f}" y="{PANELS[1][2]+20}" fill="{mut}" font-size="13" text-anchor="middle">{s}</text>')
    o.append(f'<text x="{(L+W-R)/2}" y="{H-14}" fill="{ink}" font-size="14" text-anchor="middle">Optimizer step (65,536 tokens each)</text>')
    lx,ly=L+250,70
    for i,((c,d),lab) in enumerate(zip(sty,('baseline: warm-up 15 steps, clip 1.0','baseline, run again','no warm-up','no clipping'))):
        o.append(f'<line x1="{lx}" x2="{lx+28}" y1="{ly+i*20}" y2="{ly+i*20}" stroke="{c}" stroke-width="2.5"{d}/>')
        o.append(f'<text x="{lx+36}" y="{ly+i*20+4}" fill="{ink}" font-size="13">{lab}</text>')
    o.append(f'<text x="{lx+36}" y="{ly+84}" fill="{mut}" font-size="13">dotted: unigram level, 7.59</text>')
    o.append('</svg>'); return '\n'.join(o)
